// Переключатель меняется только на экране, «שמירת החוקים» не нажимается; запросы записи отклоняются.
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { blockRuleWrites, openExpertScreen, cancelConfirmIfShown } from '../helpers/expert';

test.use({ storageState: path.join(__dirname, '../../../auth/expert.json') });

const WARNING = /יירשמו כאירוע, בלי אזעקה ובלי התרעה לטלפונים האחרים/;

test.describe('Экран «חוקי זיהוי» — эксперт', () => {
  test.afterEach(async ({ page }) => { await cancelConfirmIfShown(page); });

  test('«רק ראש מתחת למים והיעלמות» — предупреждение, «בכל התרחישים» — предупреждение исчезает #89216b @desktop @prod-safe', async ({ page }) => {
    const writes = await blockRuleWrites(page);
    await openExpertScreen(page);

    const onlyHead = page.getByText('רק ראש מתחת למים והיעלמות', { exact: true }).filter({ visible: true });
    const all = page.getByText('בכל התרחישים', { exact: true }).filter({ visible: true });
    await expect(page.getByText(WARNING)).toHaveCount(0);

    // AC6: предупреждение
    await onlyHead.click();
    const warning = page.getByText(WARNING).filter({ visible: true });
    await expect(warning).toBeVisible();
    await expect(warning).toContainText('חוסר תנועה, תנוחה אנכית ועצירה פתאומית');

    // AC6: «אחר כך מחזירים ל«בכל התרחישים»»
    await all.click();
    await expect(page.getByText(WARNING)).toHaveCount(0);
    expect(writes.saveCalls).toBe(0);
  });
});
